"""
GREENROOM - build hook (pure Python: the builder runs it with the system python3).

Generates greenroom_pkg.vhd from the data fitted to photos/television.jpg (a painted paper collage):

  C_GRMAP 12288 x 4 (12 EBR): the layout map.  96 x 120 cells of 9 virtual px (the page is 864 x 1080
          virtual px, centred in the frame), address row*96 + col, each cell the index (0..15) of its colour
          in the bank palette of its tile (4 bank rows of 30 cells x 3 bank columns of 32 cells).  The 16
          colours per tile are a k-means fit of the photo's CELL MEANS (sorted dark -> light), so region
          means match the photo.  Entries 11520.. are unused (zero).
  C_GRPAL 256 x 16 (1 EBR): bank*16 + index -> {Y6, U5, V5}: Y10 = 128 + 13*Y6 (luma pre-boosted 16/13 with a
          knee above 860, so the shell's 13/16 output scale returns the photo's tones), U10 = 512 + 16*(U5 - 16),
          V10 = 512 + 16*(V5 - 16), hardware convention (U = Cr, V = Cb).  Entries 192..255 unused.
  C_GRGLY 256 x 16 (1 EBR): the caption "cture yourself on this pa" (DejaVu Sans Bold fitted to the photo's
          letters), 16 rows x 256 columns; address row*16 + col/16, bit col%16.
"""
import os

HERE = os.path.dirname(os.path.abspath(__file__))
MAP = ""
PAL = ""
GLY = ""


def words(hexstr, n):
    return [int(hexstr[i:i + n], 16) for i in range(0, len(hexstr), n)]


def vhdl_array(name, typ, vals, fmt, per_line):
    out = ["    constant %s : %s := (" % (name, typ)]
    lines = []
    for i in range(0, len(vals), per_line):
        lines.append("        " + ", ".join(fmt % v for v in vals[i:i + per_line]))
    out.append(",\n".join(lines))
    out.append("    );")
    return "\n".join(out)


def main():
    m = words(MAP, 1)
    p = words(PAL, 4)
    g = words(GLY, 4)
    assert len(m) == 12288 and len(p) == 256 and len(g) == 256
    s = []
    s.append("-- greenroom_pkg.vhd -- GENERATED by greenroom.py; edit the generator, not this file.")
    s.append("library ieee;\nuse ieee.std_logic_1164.all;\nuse ieee.numeric_std.all;\n")
    s.append("package greenroom_pkg is")
    s.append("    type t_map is array(0 to 12287) of std_logic_vector(3 downto 0);")
    s.append("    type t_w16 is array(0 to 255) of std_logic_vector(15 downto 0);")
    s.append(vhdl_array("C_GRMAP", "t_map", m, 'x"%x"', 32))
    s.append(vhdl_array("C_GRPAL", "t_w16", p, 'x"%04X"', 16))
    s.append(vhdl_array("C_GRGLY", "t_w16", g, 'x"%04X"', 16))
    s.append("end package greenroom_pkg;")
    with open(os.path.join(HERE, "greenroom_pkg.vhd"), "w") as f:
        f.write("\n".join(s) + "\n")


if __name__ == "__main__":
    main()
